css:
/* Latest posts cannot leave out the post being read, so it asks for four and
   this post's own card is hidden (or, when it is not among them, the fourth). */
[data-bz-node="related-posts"] .bz-card[href$="/hyundai-translead-trailers-built-for-efficiency"] { display: none; }
[data-bz-node="related-posts"] .bz-grid:not(:has(.bz-card[href$="/hyundai-translead-trailers-built-for-efficiency"])) > .bz-card:nth-child(n+4) { display: none; }

/* The hero photograph is framed a little high, as the design frames it. */
[data-bz-section="post-hero"] [data-bz-node="ph-photo"] img { object-position: center 55%; }

/* Its type cards: 24px in, the title 10px over a 14px list. */
[data-bz-node="art-body"] .ss-cl--type,
[data-bz-node="art-body"] .ss-cl--type3 { gap: 24px; }
[data-bz-node="art-body"] .ss-cl--type { gap: 28px; }
[data-bz-node="art-body"] .ss-cl--type .ss-cl__card { padding: 24px; }
[data-bz-node="art-body"] .ss-cl--type .ss-cl__t { margin: 0 0 10px; }
[data-bz-node="art-body"] :is(.ss-cl--type, .ss-cl--type3) .ss-cl__list { margin: 0; padding-left: 18px; }
[data-bz-node="art-body"] :is(.ss-cl--type, .ss-cl--type3) .ss-cl__list li { font-size: 14px; }

/* A type card's sentence is set as body text, as the article's paragraphs are. */
[data-bz-node="art-body"] :is(.ss-cl--type, .ss-cl--type3) .ss-cl__p { font-size: 17px; line-height: 1.8; margin: 0 0 18px; }

[data-bz-node="art-body"] > [data-bz-node="actions-partner-3"] .bz-btns { margin: 8px 0 34px; }
